Add({
	kind = "figure",
	id = "aiden-perenolde",
	title = "Aiden Perenolde",
	aliases = { "King Perenolde", "Lord Aiden Perenolde" },
	subtitle = "The Traitor King of Alterac",
	tier = "B",
	region = "alterac-mountains",
	allegiance = "Kingdom of Alterac",
	unlock = {
		{ type = "read" },
	},
	hint = [=[Learn the story of the king who sold his mountains to the Horde.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Aiden Perenolde was the last king of {link:alterac-mountains}Alterac{/link}. He was a soft-spoken, cultured man who owned a fine sword and never used it. His rivals in the {link:alliance}Alliance{/link} thought him a coward. He thought himself the only king wise enough to see that the {link:horde}Horde{/link} could not be beaten. In the {link:second-war}Second War{/link} he betrayed the Alliance to save his own realm, and in doing so he lost it.]=],
		},
		{
			title = "Significance",
			text = [=[Perenolde's treachery is the reason {link:alterac-mountains}Alterac{/link} lies in ruins. His heirs still dream of the crown he forfeited, and the {link:syndicate}Syndicate{/link} they lead is his bitter legacy.]=],
		},
		{
			title = "Deeds",
			text = [=[• He joined the {link:alliance}Alliance of Lordaeron{/link} only reluctantly, and doubted it from the start.
• He barricaded the passes of his mountains, then made a secret pact with {link:orgrim-doomhammer}Orgrim Doomhammer{/link} and opened them.
• He murdered the messenger who brought {link:anduin-lothar}Lothar{/link}'s call for troops, and hid the body in his castle.
• He was deposed by {link:terenas-menethil}King Terenas{/link} and confined to his palace in the ruined capital.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle records when or how Aiden Perenolde died. In captivity his wits are said to have failed him. His family was kept under watch, and his eldest son, {link:lord-aliden-perenolde}Aliden{/link}, tried in vain to clear their name.]=],
		},
	},
	chapters = {
		{
			key = "the-open-passes",
			title = "The Open Passes",
			hint = "Learn why the Horde crossed Alterac so quickly.",
			unlock = {
				{ type = "read" },
			},
			text = [=[When the {link:horde}Horde{/link} came to the mountains, Perenolde sent a bird to its Warchief and met him by night. He found the {link:orcs}orc{/link} cultured and honorable. They made a treaty: the Horde would pass unharmed, and {link:alterac-mountains}Alterac{/link} would be spared. Perenolde moved his soldiers north and left the southern passes empty. A crossing that should have taken months took two days. Only when {link:thoras-trollbane}Thoras Trollbane{/link} of {link:stromgarde-keep}Stromgarde{/link} came into Alterac and turned Perenolde's own general against him were the passes closed again.]=],
		},
		{
			key = "the-lost-heirloom",
			title = "The Lost Heirloom",
			hint = "Recover the tiara of the royal house of Alterac.",
			unlock = {
				{ type = "quest", id = 543 },
			},
			text = [=[When {link:alterac-mountains}Alterac{/link} fell, the Perenolde Tiara was lost. Dwarven jewelers had made it, and its emeralds were the finest they had. Collectors in {link:stormwind-city}Stormwind{/link} still want it. It turned up at last in the hands of an {link:ogres}ogre{/link} mage who hunts for treasure in the ruins of the very city where the king once wore it.]=],
		},
	},
	mentions = {
		{
			text = "The Perenolde Tiara",
			unlock = {
				{ type = "quest", id = 543 },
			},
		},
		{
			text = "Noble Deaths, against the nobles of his fallen court",
			unlock = {
				{ type = "quest", id = 512 },
			},
		},
	},
	bonds = {
		{ id = "lord-aliden-perenolde", name = "Lord Aliden Perenolde", note = "his eldest son" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "his secret ally" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "the king who deposed him" },
		{ id = "grel-borg-the-miser", name = "Grel'borg the Miser", note = "holds his family's tiara" },
