Add({
	kind = "topic",
	id = "crushridge-ogres",
	title = "Crushridge Ogres",
	aliases = { "Crushridge", "Crushridge ogre", "Crushridge clan" },
	category = "group",
	region = "alterac-mountains",
	unlock = {
		{ type = "read" },
		{ type = "target" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Crushridge are a warband of {link:ogres}ogres{/link} who have taken the ruins of the old capital of {link:alterac-mountains}Alterac{/link} for their own. Brutes, maulers, warmongers, enforcers and mages fill the streets where the kings of Alterac once rode. They have dug a great mound in the hills nearby and a second deeper in the mountains, and their patrols guard the crossroads toward {link:tarren-mill}Tarren Mill{/link}.]=],
		},
		{
			title = "The Crown of Will",
			text = [=[The Crushridge did not come to {link:alterac-mountains}Alterac{/link} of their own will. Their warlord {link:mug-thol}Mug'thol{/link} was bound to the service of {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, and she sent his warband to the mountains to recover a relic called the Crown of Will. Mug'thol found the crown and put it on. It freed him from the Dark Lady's hold, and his ogres followed him into the ruins as their own masters. Three lieutenants, Targ, Muckrake and Glommus, stand at his side, and the {link:ogres}ogre{/link} mage {link:grel-borg-the-miser}Grel'borg{/link} hunts the city for treasure.]=],
		},
		{
			title = "Enemies on Every Side",
			text = [=[The {link:forsaken}Forsaken{/link} of {link:tarren-mill}Tarren Mill{/link} want the crown, and the heads of {link:mug-thol}Mug'thol{/link} and his lieutenants with it. The soldiers of {link:southshore}Southshore{/link} fear that the ogres will come down into the foothills, and their marshal pays a bounty for every {link:ogres}ogre{/link} slain. The ogres have also fought the {link:syndicate}Syndicate{/link} for the ruins of the kingdom both claim.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "argus-wake",
	title = "Argus Wake",
	aliases = { "the Argus Wake" },
	category = "group",
	region = "alterac-mountains",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 537 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Argus Wake is a secret order that has made itself the ally of the {link:syndicate}Syndicate{/link} in {link:alterac-mountains}Alterac{/link}. Its shadow mages wait in the {link:the-uplands}Uplands{/link}, and its hierophant, the {link:orcs}orc{/link} {link:nagaz}Nagaz{/link}, stands beside {link:lord-aliden-perenolde}Lord Aliden Perenolde{/link}. The nobles of Alterac believe they have found powerful friends. They are wrong.]=],
		},
		{
			title = "The Letter",
			text = [=[The truth came to light in a letter found in a {link:syndicate}Syndicate{/link} camp. It was written in a cipher so rare that even the loremaster of {link:southshore}Southshore{/link} could not read it, and it had to be carried to a prospector in {link:ironforge}Ironforge{/link}. {link:nagaz}Nagaz{/link} had written it to the head of the Wake, whom he addressed as his master, appointed by a council. The Syndicate, he wrote, would win back {link:alterac-mountains}Alterac{/link} with the Wake's guidance, then take {link:stromgarde-keep}Stromgarde{/link}. With a nation and a base of power of their own, the Wake would then prepare the way for what he called the Third Host. He signed it in the name of {link:sargeras}Sargeras{/link}.]=],
		},
		{
			title = "What Remains Unknown",
			text = [=[{link:magistrate-henry-maleb}Magistrate Maleb{/link} of {link:southshore}Southshore{/link} sent hunters after {link:nagaz}Nagaz{/link} and his mages. Even so, the magistrate knows that Nagaz was only a servant. Who leads the Argus Wake, and how far its roots run, no one in Southshore can say.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "stormpike-guard",
	title = "Stormpike Guard",
	aliases = { "Stormpike Expedition", "Stormpikes" },
	category = "group",
	region = "alterac-mountains",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Stormpike Guard is an expedition of {link:dwarves}dwarves{/link} of the Stormpike clan in {link:alterac-valley}Alterac Valley{/link}, under the command of General {link:vanndar-stormpike}Vanndar Stormpike{/link}. From their fortress of Dun Baldar in the north of the valley, they search the land for ore and for relics of their past. {link:humans}Humans{/link}, gnomes and night elves of the {link:alliance}Alliance{/link} fight in their ranks.]=],
		},
		{
			title = "The Imperative",
			text = [=[The expedition has become a war. King {link:magni-bronzebeard}Magni Bronzebeard{/link} has declared the taking of {link:alterac-mountains}Alterac{/link}'s valleys a duty of the {link:kingdom-of-ironforge}Kingdom of Ironforge{/link}, and the Stormpikes fight to claim them against the Winterax trolls and the orcs of the {link:frostwolf-clan}Frostwolf Clan{/link}. The scholars of the {link:explorers-league}Explorers' League{/link} march with them, sure that the valley holds artifacts worth the fight. The orcs call them invaders. The dwarves call the valley theirs by right.]=],
		},
		{
			title = "In the Present Day",
			text = [=[Outside the tunnel to the valley, Stormpike officers receive the soldiers of the {link:alliance}Alliance{/link}, test them in the caverns of the valley and give them the insignia of the Guard. The dwarves' rams, bred on the Amberstill ranch in {link:dun-morogh}Dun Morogh{/link}, go north to reinforce the expedition.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "frostwolf-clan",
	title = "Frostwolf Clan",
	aliases = { "Frostwolves", "Frostwolf clan", "Frostwolf orcs" },
	category = "group",
	region = "alterac-mountains",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Frostwolf clan is an {link:orcs}orc{/link} clan that makes its home in {link:alterac-valley}Alterac Valley{/link}. It is the clan of {link:thrall}Thrall{/link}'s father, and the Warchief holds it dear. Its warriors ride the great white wolves of the mountains, and its elder shaman, {link:drek-thar}Drek'Thar{/link}, leads it from Frostwolf Keep in the south of the valley.]=],
		},
		{
			title = "The Exile",
			text = [=[On Draenor the Frostwolves were a proud clan under their chieftain, Durotan. When the orcs came to {link:azeroth}Azeroth{/link}, Durotan spoke against {link:gul-dan}Gul'dan{/link} and the dark path the {link:horde}Horde{/link} had taken. For that, his clan was banished to the {link:alterac-mountains}Alterac Mountains{/link}. Durotan and his mate later left the valley, and both were murdered by agents of Gul'dan. Their infant son was found by a human officer, who raised him as a slave in {link:durnholde-keep}Durnholde{/link}. The Frostwolves endured the cold and the long years alone, and far from the fel magic of the Horde, their shamans relearned the ways of the spirits.]=],
		},
		{
			title = "The Return of the Son",
			text = [=[Years later a young {link:orcs}orc{/link} came to their camp, a runaway from {link:durnholde-keep}Durnholde{/link}. He was Durotan's son. {link:drek-thar}Drek'Thar{/link} taught him the ways of the shaman, and from the valley {link:thrall}Thrall{/link} went out to free the orcs of the camps and to build a new {link:horde}Horde{/link}.]=],
		},
		{
			title = "In the Present Day",
			text = [=[Now the dwarves of the {link:stormpike-guard}Stormpike Guard{/link} have come into the valley. The Frostwolves will not surrender their home, and the {link:horde}Horde{/link} has answered their call.]=],
